WITH scored AS (SELECT *, SUM(rating) OVER w_hist AS cumulative_rating, STDDEV_SAMP(rating) OVER w_running AS country_stddev_samp_rating, SUM(rating) OVER w_ordered AS country_sum_rating, CUME_DIST() OVER (PARTITION BY country ORDER BY rating DESC NULLS LAST) AS rating_cume_dist FROM suppliers WINDOW w_hist AS (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY country), w_ordered AS (PARTITION BY country, city)) SELECT CASE WHEN cumulative_rating >= 18 THEN 'HIGH' ELSE 'LOW' END AS cumulative_rating_tier, country, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT_IF(city = 'Tokyo') AS tokyo_events, MIN(country_stddev_samp_rating) AS min_country_stddev_samp_rating, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, ROUND(SUM(country_sum_rating) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS country_sum_rating_per_singapore, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count FROM scored GROUP BY 1, 2;
